interface Handler { setNext(h: Handler): Handler; handle(req: string): string | null }
class AuthHandler implements Handler { private next?: Handler; setNext(h: Handler){ this.next = h; return h }
  handle(req: string){ if (req === 'auth') return 'auth ok'; return this.next ? this.next.handle(req) : null }
}
class LogHandler implements Handler { private next?: Handler; setNext(h: Handler){ this.next = h; return h }
  handle(req: string){ if (req === 'log') return 'logged'; return this.next ? this.next.handle(req) : null }
}
const chain = new AuthHandler(); chain.setNext(new LogHandler()); const result = chain.handle('log');

